import{_ as a,o as t,c as l,ag as i}from"./chunks/framework.DTisvaUJ.js";const m=JSON.parse('{"title":"更新履歴","description":"Mutelinkの更新履歴。VRChat向けの音声認識・読み上げ・翻訳・VRキーボードなどの主な機能追加と修正を確認できます。","frontmatter":{"description":"Mutelinkの更新履歴。VRChat向けの音声認識・読み上げ・翻訳・VRキーボードなどの主な機能追加と修正を確認できます。","head":[["meta",{"name":"robots","content":"index, follow, max-image-preview:large"}],["link",{"rel":"canonical","href":"https://utyujinn.github.io/Mutelink-releases/about/changelog"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mutelink"}],["meta",{"property":"og:locale","content":"ja_JP"}],["meta",{"property":"og:title","content":"更新履歴 | Mutelink"}],["meta",{"property":"og:description","content":"Mutelinkの更新履歴。VRChat向けの音声認識・読み上げ・翻訳・VRキーボードなどの主な機能追加と修正を確認できます。"}],["meta",{"property":"og:url","content":"https://utyujinn.github.io/Mutelink-releases/about/changelog"}],["meta",{"property":"og:image","content":"https://utyujinn.github.io/Mutelink-releases/images/og-image.png"}],["meta",{"property":"og:image:width","content":"1920"}],["meta",{"property":"og:image:height","content":"1080"}],["meta",{"property":"og:image:alt","content":"Mutelink"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"更新履歴 | Mutelink"}],["meta",{"name":"twitter:description","content":"Mutelinkの更新履歴。VRChat向けの音声認識・読み上げ・翻訳・VRキーボードなどの主な機能追加と修正を確認できます。"}],["meta",{"name":"twitter:image","content":"https://utyujinn.github.io/Mutelink-releases/images/og-image.png"}],["meta",{"name":"twitter:image:alt","content":"Mutelink"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://utyujinn.github.io/Mutelink-releases/about/changelog"}],["link",{"rel":"alternate","hreflang":"en","href":"https://utyujinn.github.io/Mutelink-releases/en/about/changelog"}],["link",{"rel":"alternate","hreflang":"zh-Hans","href":"https://utyujinn.github.io/Mutelink-releases/zh/about/changelog"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://utyujinn.github.io/Mutelink-releases/ko/about/changelog"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://utyujinn.github.io/Mutelink-releases/about/changelog"}]]},"headers":[],"relativePath":"about/changelog.md","filePath":"about/changelog.md"}'),n={name:"about/changelog.md"};function r(o,e,h,u,s,c){return t(),l("div",null,[...e[0]||(e[0]=[i('<h1 id="更新履歴" tabindex="-1">更新履歴 <a class="header-anchor" href="#更新履歴" aria-label="Permalink to &quot;更新履歴&quot;">​</a></h1><p>主な変更だけを載せています。新しいものが上です。インストーラーは<a href="https://github.com/utyujinn/Mutelink-releases/releases" target="_blank" rel="noreferrer">Releases</a>にあります。</p><h2 id="v2-0-0-2026年11月15日" tabindex="-1">v2.0.0(2026年11月15日) <a class="header-anchor" href="#v2-0-0-2026年11月15日" aria-label="Permalink to &quot;v2.0.0(2026年11月15日)&quot;">​</a></h2><p>画面と機能を、大きく作り直しました。</p><h3 id="画面" tabindex="-1">画面 <a class="header-anchor" href="#画面" aria-label="Permalink to &quot;画面&quot;">​</a></h3><ul><li>画面と操作を、全面的に新しくしました</li></ul><h3 id="読み上げ" tabindex="-1">読み上げ <a class="header-anchor" href="#読み上げ" aria-label="Permalink to &quot;読み上げ&quot;">​</a></h3><ul><li>Irodori-TTSが使うVRAMを、大幅に減らしました。速度も上がりました</li><li>日本語以外の9言語も読み上げられる、Qwen3-TTSを追加しました(<a href="/Mutelink-releases/compare/voices">読み上げの声の聞き比べ</a>)</li></ul><h3 id="音声認識" tabindex="-1">音声認識 <a class="header-anchor" href="#音声認識" aria-label="Permalink to &quot;音声認識&quot;">​</a></h3><ul><li>このPCで動く音声認識のモデルを、新しくしました。日本語の認識の精度が、大幅に上がりました(Parakeet 日本語 TDT、Haas-ja、Qwen3-ASR。<a href="/Mutelink-releases/compare/speech-recognition">比較</a>)</li></ul><h3 id="翻訳" tabindex="-1">翻訳 <a class="header-anchor" href="#翻訳" aria-label="Permalink to &quot;翻訳&quot;">​</a></h3><ul><li>自分の言葉を翻訳して、読み上げと、チャットボックスで送れます</li><li>聞こえた声を、翻訳して読めます</li><li>翻訳エンジンは、PLaMo、TranslateGemma、Azure Translator(クラウド)から選べます(<a href="/Mutelink-releases/compare/translation">比較</a>)</li></ul><h3 id="vrキーボード" tabindex="-1">VRキーボード <a class="header-anchor" href="#vrキーボード" aria-label="Permalink to &quot;VRキーボード&quot;">​</a></h3><ul><li>日本語4種類、中国語4種類、韓国語2種類、英語、記号、テンプレートの入力方式が使えます</li><li>なぞり入力が使えます</li></ul><h3 id="そのほか" tabindex="-1">そのほか <a class="header-anchor" href="#そのほか" aria-label="Permalink to &quot;そのほか&quot;">​</a></h3><ul><li>相手が話している間は、自分の声を出さずに待つ機能を追加しました(オン・オフできます)</li><li>チャットボックスに文字を出すタイミングを、声が出たときにできます(オン・オフできます)</li><li>コントロールパネルをキーボードから分けて、手に付けられるようにしました(カスタマイズ拡張が必要です)</li></ul><h2 id="v1-0-3-2026年11月5日" tabindex="-1">v1.0.3(2026年11月5日) <a class="header-anchor" href="#v1-0-3-2026年11月5日" aria-label="Permalink to &quot;v1.0.3(2026年11月5日)&quot;">​</a></h2><ul><li>Parakeet、Whisper、Googleの音声認識で、音の重なりや欠落が起きる問題を修正しました</li></ul><h2 id="v1-0-2-2026年10月18日" tabindex="-1">v1.0.2(2026年10月18日) <a class="header-anchor" href="#v1-0-2-2026年10月18日" aria-label="Permalink to &quot;v1.0.2(2026年10月18日)&quot;">​</a></h2><ul><li>親指下側ボタンの単押しを、好きな動作に変えられるようにしました</li><li>不具合や要望を、開発者に匿名で送る「不具合・要望を送る」を追加しました</li><li>更新したあとの最初の起動で、変更点を表示するようにしました</li><li>操作に失敗したときに、エラーの表示が出るようにしました</li></ul><h2 id="v1-0-1-2026年10月16日" tabindex="-1">v1.0.1(2026年10月16日) <a class="header-anchor" href="#v1-0-1-2026年10月16日" aria-label="Permalink to &quot;v1.0.1(2026年10月16日)&quot;">​</a></h2><ul><li>VR背景の画像の追加と読み込みの不具合を、修正しました</li><li>「起動時に更新を知らせる」の設定を追加しました</li></ul><h2 id="v1-0-0-2026年10月10日" tabindex="-1">v1.0.0(2026年10月10日) <a class="header-anchor" href="#v1-0-0-2026年10月10日" aria-label="Permalink to &quot;v1.0.0(2026年10月10日)&quot;">​</a></h2><p>最初の正式版です。</p>',24)])])}const p=a(n,[["render",r]]);export{m as __pageData,p as default};
